package com.avizero.avidrive.api;

import com.avizero.avidrive.domain.*; import com.avizero.avidrive.repository.*; import com.avizero.avidrive.security.AuthUser; import java.time.*; import java.util.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/search") public class SearchController {private final FolderRepository folders;private final StoredFileRepository files;private final SharedFolderMemberRepository members;public SearchController(FolderRepository f,StoredFileRepository s,SharedFolderMemberRepository m){folders=f;files=s;members=m;}
 @GetMapping public Map<String,Object> search(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="all")String type,@RequestParam(required=false)String date_from,@RequestParam(required=false)String date_to,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size,Authentication a){Long uid=((AuthUser)a.getPrincipal()).id();Set<Long> owners=new HashSet<>();owners.add(uid);members.findByIdUserId(uid).forEach(m->folders.findById(m.id.folderId).ifPresent(f->owners.add(f.ownerId)));String query=q.toLowerCase();List<Map<String,Object>> fs=folders.findAll().stream().filter(f->owners.contains(f.ownerId)&&f.name.toLowerCase().contains(query)&&(!"files".equals(type))).map(f->Map.<String,Object>of("id",f.id,"name",f.name,"type","FOLDER","parent_id",f.parentId)).limit(100).toList();List<Map<String,Object>> docs=files.findAll().stream().filter(f->owners.contains(f.ownerId)&&f.name.toLowerCase().contains(query)&&(!"folders".equals(type))).map(f->Map.<String,Object>of("id",f.id,"name",f.name,"type","FILE","folder_id",f.folderId,"size_bytes",f.sizeBytes)).limit(100).toList();return Map.of("folders",fs,"files",docs,"page",page,"size",size);}}
